  firstName: '',
  lastName: '',
  email: '',
  company: '',
  category: '',
  message: '',
  agreement: false
})

// Helper function for contact icons
const getContactIcon = (type: string) => {
  const iconMap: Record<string, string> = {
    email: 'mdi-email',
    office: 'mdi-office-building',
    hours: 'mdi-clock-outline'
  }
  return iconMap[type] || 'mdi-phone'
}

// 問い合わせカテゴリ
const categories = [
  'サービスに関するお問い合わせ',
  'コーヒー事業について',
  '展示・イベント運営について',
  'LAB・研究開発について',
  'クラブ・コミュニティについて',
  '採用について',
  'その他'
]

// 連絡先情報
const contactInfo = [
  {
    title: 'Email',
    type: 'email',
    details: [
      'info@no-trace.jp',
      'support@no-trace.jp'
    ]
  },
  {
    title: 'Office',
    type: 'office',
    details: [
      '東京都渋谷区',
      '(設立準備中につき詳細は後日公開)'
    ]
  },
  {
    title: 'Business Hours',
    type: 'hours',
    details: [
      '平日 9:00-18:00',
      '土日祝日休業'
    ]
  }
]

// フォームバリデーション
const validateForm = () => {
  errors.value = {
    firstName: '',
    lastName: '',
    email: '',
    category: '',
    message: '',
    agreement: ''
  }

  let isValid = true

  if (!form.value.firstName) {
    errors.value.firstName = '姓を入力してください'
    isValid = false
  } else if (form.value.firstName.length > 50) {
    errors.value.firstName = '50文字以内で入力してください'
    isValid = false
  }

  if (!form.value.lastName) {
    errors.value.lastName = '名を入力してください'
    isValid = false
  } else if (form.value.lastName.length > 50) {
    errors.value.lastName = '50文字以内で入力してください'
    isValid = false
  }

  if (!form.value.email) {
    errors.value.email = 'メールアドレスを入力してください'
    isValid = false
  } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(form.value.email)) {
    errors.value.email = '正しいメールアドレスを入力してください'
    isValid = false
  }

  if (!form.value.category) {
    errors.value.category = 'お問い合わせ種別を選択してください'
    isValid = false
  }

  if (!form.value.message) {
    errors.value.message = 'お問い合わせ内容を入力してください'
    isValid = false
  } else if (form.value.message.length > 1000) {
    errors.value.message = '1000文字以内で入力してください'
    isValid = false
  }

  if (!form.value.agreement) {
    errors.value.agreement = 'プライバシーポリシーに同意してください'
    isValid = false
  }

  return isValid
}

// 表单提交
const submitForm = async () => {
  if (!validateForm()) {
    return
  }

  loading.value = true

  try {
    // ここで実際のAPI呼び出しを行う
    await new Promise(resolve => setTimeout(resolve, 2000)) // 模拟API调用

    // 成功処理
    alert('お問い合わせを受け付けました。ありがとうございます。')

    // フォームリセット
    form.value = {
      firstName: '',
      lastName: '',
      email: '',
      company: '',
      category: '',
      message: '',
      agreement: false
    }

    // エラーメッセージクリア
    errors.value = {
      firstName: '',
      lastName: '',
      email: '',
      category: '',
      message: '',
      agreement: ''
    }
  } catch (error) {
    // エラー処理
    alert('送信に失敗しました。もう一度お試しください。')
  } finally {
    loading.value = false
  }
}

